export const SECLAB_SECRET_RULES: readonly SeclabSecretRule[] = table.rules;

export const SECLAB_SECRET_GLOBAL_ALLOW: { readonly regexes: readonly { readonly source: string; readonly flags: string }[]; readonly stopwords: readonly string[] } = table.global;
